Patient Portal Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Patient Portal Container container

Container_Boundary("Patient Portal Container", "Patient Portal Container") {
    Component("Patient Portal API Router", "Patient Portal API Router", "Node.js/NestJS", "Routes client requests and handles API routing for the patient portal.")
    Component("Patient Portal Service", "Patient Portal Service", "Go", "Coordinates resource checks and business logic for patient workflows.")
}

Rel("Patient Portal API Router", "Patient Portal Service", "Delegates request handling and coordination", "Internal IPC")

@enduml

EMR Core Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the EMR Core Service container

Container_Boundary(emr_core_service, "EMR Core Service") {
    Component(ChartEncounterManager, "Chart & Encounter Manager", "Java 21 / .NET 8", "Manages patient charts, clinical encounters, and core medical records workflows.")
    Component(AuthorizationPolicyComponent, "Authorization & Policy Component", "Java 21 / .NET 8", "Handles access control, permissions, and security policies for clinical operations.")
}

Rel(ChartEncounterManager, AuthorizationPolicyComponent, "Validates clinical requests against security policies")

@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_broker, "Message Broker") {
    Component(Connection & Auth Manager, "Connection & Auth Manager", "NATS JetStream / Kafka", "Handles connection management and authentication for message broker clients.")
    Component(Routing & Delivery Engine, "Routing & Delivery Engine", "NATS JetStream / Kafka", "Routes and delivers message frames across the messaging infrastructure.")
    Component(Replication & Persistence Engine, "Replication & Persistence Engine", "NATS JetStream / Kafka", "Persists message streams and commits offsets using distributed consensus.")
}

System_Ext(Audit & Compliance Daemon, "Audit & Compliance Daemon", "Go")

Rel(Connection & Auth Manager, Routing & Delivery Engine, "Forwards authenticated client frames", "gRPC")
Rel(Routing & Delivery Engine, Replication & Persistence Engine, "Persists message streams and commits offsets", "Raft consensus protocol / JetStream API")
Rel(Routing & Delivery Engine, Audit & Compliance Daemon, "Streams real-time telemetry logs", "Syslog over TLS")
@enduml
